-- Dedicated public H2 only. No DROP, DELETE, or imported records.
CREATE TABLE IF NOT EXISTS users (user_id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255),email VARCHAR(255),password VARCHAR(255),created_at DATETIME(6));
CREATE TABLE IF NOT EXISTS goals (goal_id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,goal_name VARCHAR(255),goal_type VARCHAR(255),exam_date DATE,target_score VARCHAR(255),current_level VARCHAR(255),weak_point VARCHAR(255),daily_study_time INT,preferred_study_method VARCHAR(255),created_at DATETIME(6),UNIQUE KEY uq_goal_owner(goal_id,user_id),CONSTRAINT fk_goal_user FOREIGN KEY(user_id) REFERENCES users(user_id));
CREATE TABLE IF NOT EXISTS subjects (subject_id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,goal_id BIGINT NOT NULL,subject_name VARCHAR(255),difficulty VARCHAR(255),priority_level VARCHAR(255),current_confidence VARCHAR(255),created_at DATETIME(6),UNIQUE KEY uq_subject_owner(subject_id,user_id),CONSTRAINT fk_subject_goal FOREIGN KEY(goal_id,user_id) REFERENCES goals(goal_id,user_id));
CREATE TABLE IF NOT EXISTS study_logs (log_id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,subject_id BIGINT NOT NULL,study_date DATE,study_minutes INT,study_content VARCHAR(255),understanding_score INT,focus_score INT,fatigue_score INT,study_method VARCHAR(255),total_questions INT,correct_count INT,wrong_count INT,wrong_reason VARCHAR(255),difficult_topic VARCHAR(255),completed VARCHAR(255),memo VARCHAR(255),created_at DATETIME(6),CONSTRAINT fk_log_subject FOREIGN KEY(subject_id,user_id) REFERENCES subjects(subject_id,user_id));
CREATE TABLE IF NOT EXISTS study_questions (question_id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,subject VARCHAR(255),situation VARCHAR(255),understanding VARCHAR(255),question TEXT,ai_advice TEXT,created_at DATETIME(6),UNIQUE KEY uq_question_owner(question_id,user_id),CONSTRAINT fk_question_user FOREIGN KEY(user_id) REFERENCES users(user_id));
CREATE TABLE IF NOT EXISTS ai_responses (response_id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,goal_id BIGINT,question_id BIGINT,feature VARCHAR(32) NOT NULL,requested_provider VARCHAR(32),actual_provider VARCHAR(32),model VARCHAR(150),response_source VARCHAR(16) NOT NULL,response_body MEDIUMTEXT NOT NULL,response_complete BOOLEAN,created_at DATETIME(6) NOT NULL,KEY idx_ai_response_user_feature(user_id,feature,created_at),KEY idx_ai_response_user_goal(user_id,goal_id,created_at),CONSTRAINT fk_response_goal FOREIGN KEY(goal_id,user_id) REFERENCES goals(goal_id,user_id),CONSTRAINT fk_response_question FOREIGN KEY(question_id,user_id) REFERENCES study_questions(question_id,user_id));
CREATE TABLE IF NOT EXISTS study_schedule_settings (schedule_id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,schedule_date DATE NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,busy_start TIME,busy_end TIME,updated_at DATETIME(6) DEFAULT CURRENT_TIMESTAMP(6),UNIQUE KEY uq_settings_user_date(user_id,schedule_date),CONSTRAINT fk_settings_user FOREIGN KEY(user_id) REFERENCES users(user_id));
CREATE TABLE IF NOT EXISTS study_saved_plans (plan_id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,goal_id BIGINT NOT NULL,plan_date DATE NOT NULL,source_date DATE NOT NULL,source_end_time TIME NOT NULL,plan_status VARCHAR(10) NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,busy_start TIME,busy_end TIME,plan_json MEDIUMTEXT NOT NULL,saved_at DATETIME(6) DEFAULT CURRENT_TIMESTAMP(6),UNIQUE KEY uq_saved_goal_date(user_id,goal_id,plan_date),CONSTRAINT fk_saved_goal FOREIGN KEY(goal_id,user_id) REFERENCES goals(goal_id,user_id));
